export function Refreshing({
  isRefreshing = {{isRefreshing}},
  style = "{{style}}",
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 20, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      {isRefreshing && style === "spinner" && (
        <div className="spin" style={{ display: "inline-block", width: 26, height: 26, border: "3px solid #24143022", borderTopColor: accent, borderRadius: 999 }} />
      )}
      {isRefreshing && style === "bar" && (
        <div style={{ height: 6, background: "#24143014", borderRadius: 999, overflow: "hidden" }}>
          <span className="bar" style={{ display: "block", height: "100%", width: "40%", borderRadius: 999, background: accent }} />
        </div>
      )}
      <p role="status" aria-live="polite" style={{ margin: "10px 0 0" }}>{isRefreshing ? "Refreshing existing data\u2026" : "Up to date"}</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .spin { animation: lod-ref-spin ${duration}ms linear infinite; }
          .bar { animation: lod-ref-slide ${duration}ms ease-in-out infinite; }
          @keyframes lod-ref-spin { to { transform: rotate(360deg); } }
          @keyframes lod-ref-slide { 0% { margin-left: -40%; } 100% { margin-left: 100%; } }
        }
      `}</style>
    </div>
  );
}
